{"query":"
          query FETCH_BASKET($serviceConfiguration: ServiceConfiguration!) {
            basket(serviceConfiguration: $serviceConfiguration) {
              id
              currency
              locale
              total
              coupons {
                code
              }
              items {
                brandName
                productId
                id
                name
                quantity
                subtotal
                total
                promoNames
                promoAttractMessage
                available
                images {
                  path
                }
                frequency
                period
              }
            }
          }
        ","variables":{"serviceConfiguration":{"locale":"en-GB","siteId":10,"currency":"GBP"}}}

